param(
    [string]$ProjectRoot,
    [switch]$NoDownload,
    [switch]$NoRegisterClients,
    [ValidateRange(1024, 65535)][int]$Port = 38477,
    [switch]$Help
)
$ErrorActionPreference = 'Stop'
# Generated from reviewed sources; archive contents are listed in payload-manifest.json.
# Companion version: 1.0.9; registration revision: 1.
# Shared source for the standalone Windows downloads. ASCII for PowerShell 5.1.
function Get-FirefoxInstalledRoot {
    try {
        $registration = Get-FirefoxNativeRegistration
        if ($registration) { return $registration.Root }
        return $null
    } catch { return $null }
}
function Get-FirefoxNativeRegistration {
    $registryPath = 'HKCU:\Software\Mozilla\NativeMessagingHosts\de.codex.firefox_bridge'
    $key = Get-Item -LiteralPath $registryPath -ErrorAction SilentlyContinue
    if (-not $key) { return $null }
    if (@(Get-ChildItem -LiteralPath $registryPath).Count -gt 0 -or @($key.GetValueNames()).Count -ne 1 -or @($key.GetValueNames())[0] -ne '' -or $key.GetValueKind('') -ne [Microsoft.Win32.RegistryValueKind]::String) { throw 'The registration has unexpected values or child keys; nothing removed.' }
    $registeredValue = [string]$key.GetValue('')
    $manifestPath = $registeredValue
    if ($manifestPath -notmatch '^(?:[a-zA-Z]:[\\/]|\\\\[^\\]+\\[^\\]+(?:\\|$))') { throw 'The registered manifest path is not fully qualified; nothing removed.' }
    $manifestPath = [IO.Path]::GetFullPath($manifestPath)
    $local = [IO.Path]::GetDirectoryName($manifestPath)
    if ([IO.Path]::GetFileName($local) -ne '.local' -or [IO.Path]::GetFileName($manifestPath) -ne 'de.codex.firefox_bridge.json') { throw 'The registered path does not identify this companion; nothing removed.' }
    $root = [IO.Path]::GetDirectoryName($local)
    if ($root.TrimEnd([char[]]'\/') -eq [IO.Path]::GetPathRoot($root).TrimEnd([char[]]'\/')) { throw 'The registered companion root is unsafe; nothing removed.' }
    Assert-FirefoxOrdinaryPath -Path $manifestPath
    $manifestText = $null
    if ([IO.File]::Exists($manifestPath)) {
        $manifestText = [IO.File]::ReadAllText($manifestPath)
        $manifest = $manifestText | ConvertFrom-Json
        $expectedLauncher = [IO.Path]::Combine($root, '.local\native-host.cmd')
        if ($manifest.name -ne 'de.codex.firefox_bridge' -or $manifest.type -ne 'stdio' -or @($manifest.allowed_extensions).Count -ne 1 -or $manifest.allowed_extensions[0] -ne 'firefox-codex-mcp@local.invalid' -or -not $manifest.path -or $manifest.path -notmatch '^(?:[a-zA-Z]:[\\/]|\\\\[^\\]+\\[^\\]+(?:\\|$))' -or -not [string]::Equals([IO.Path]::GetFullPath($manifest.path), $expectedLauncher, [StringComparison]::OrdinalIgnoreCase)) { throw 'The manifest does not identify this companion; nothing removed.' }
    }
    return [pscustomobject]@{ Root = $root; ManifestPath = $manifestPath; RegisteredValue = $registeredValue; ManifestText = $manifestText }
}
function Test-FirefoxGitWorkingTree {
    param([string]$Path)
    $current = [IO.Path]::GetFullPath($Path)
    while ($current) {
        if (Test-Path -LiteralPath (Join-Path $current '.git')) { return $true }
        $parent = [IO.Path]::GetDirectoryName($current)
        if ($parent -eq $current) { break }
        $current = $parent
    }
    return $false
}
function Get-FirefoxSetupRoot {
    param([string]$RequestedRoot)
    if ($RequestedRoot) {
        $selected = $RequestedRoot
    } else {
        $default = Get-FirefoxInstalledRoot
        if ($default -and (Test-FirefoxGitWorkingTree -Path $default)) {
            Write-Host 'The registered directory is a Git working tree; packaged setup will use a separate installation directory.'
            $default = $null
        }
        $existingInstallation = [bool]$default
        if (-not $default) {
            if (-not $env:LOCALAPPDATA) { throw 'LOCALAPPDATA is unavailable. Supply -ProjectRoot.' }
            $default = Join-Path $env:LOCALAPPDATA 'FirefoxCodexMCP'
        }
        Write-Host 'Codex MCP for Firefox - local companion'
        Write-Host ('Installation directory: ' + $default)
        if ($existingInstallation) { Write-Host 'Default: directory of the existing registration.' }
        else { Write-Host 'Default for a new installation: %LOCALAPPDATA%\FirefoxCodexMCP.' }
        Write-Host 'Registration updates the companion files in the selected directory.'
        $selected = Read-Host 'Directory (Enter accepts the displayed directory)'
        if (-not $selected) { $selected = $default }
    }
    if ($selected -notmatch '^(?:[a-zA-Z]:[\\/]|\\\\[^\\]+\\[^\\]+(?:\\|$))') { throw '-ProjectRoot needs a fully qualified absolute installation directory.' }
    $full = [IO.Path]::GetFullPath($selected).TrimEnd([char[]]'\/')
    if ($full.TrimEnd([char[]]'\/') -eq [IO.Path]::GetPathRoot($full).TrimEnd([char[]]'\/')) { throw 'Do not select a drive root.' }
    Assert-FirefoxOrdinaryPath -Path $full -Directory
    return $full
}
function Assert-FirefoxOrdinaryPath {
    param([string]$Path, [switch]$Directory)
    $current = [IO.Path]::GetFullPath($Path)
    $first = $true
    while ($current) {
        $item = Get-Item -LiteralPath $current -Force -ErrorAction SilentlyContinue
        if ($item) {
            if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -or (($Directory -or -not $first) -and -not $item.PSIsContainer) -or ($first -and -not $Directory -and $item.PSIsContainer)) { throw ('Unsafe installation path: ' + $current) }
        }
        $first = $false
        $parent = [IO.Path]::GetDirectoryName($current)
        if ($parent -eq $current) { break }
        $current = $parent
    }
}


function Expand-FirefoxSetupPayload {
    param([Parameter(Mandatory = $true)][string]$Root)
    $compressed = [Convert]::FromBase64String('')
    $sha = [Security.Cryptography.SHA256]::Create()
    try {
        $actual = [BitConverter]::ToString($sha.ComputeHash($compressed)).Replace('-', '').ToLowerInvariant()
        if ($actual -ne 'cd7482528d8b176d8b90f9d9c44f91488d95e63c4f1ba6fc94e6e5a9598dca58') { throw 'Companion archive checksum failed.' }
    } finally { $sha.Dispose() }
    $inputStream = New-Object IO.MemoryStream(,$compressed)
    $gzip = New-Object IO.Compression.GZipStream($inputStream, [IO.Compression.CompressionMode]::Decompress)
    $reader = New-Object IO.StreamReader($gzip, [Text.Encoding]::UTF8)
    try { $payload = $reader.ReadToEnd() | ConvertFrom-Json }
    finally { $reader.Dispose(); $gzip.Dispose(); $inputStream.Dispose() }
    if ($payload.schemaVersion -ne 1 -or $payload.version -ne '1.0.9' -or @($payload.files).Count -gt 200) { throw 'Unexpected companion payload.' }
    $Root = [IO.Path]::GetFullPath($Root)
    Assert-FirefoxOrdinaryPath -Path $Root -Directory
    if (Test-FirefoxGitWorkingTree -Path $Root) { throw 'Packaged setup cannot overwrite a Git working tree. Choose a separate installation directory; use install.ps1 for development.' }
    $packagePath = Join-Path $Root 'package.json'
    Assert-FirefoxOrdinaryPath -Path $packagePath
    if ([IO.File]::Exists($packagePath)) {
        $previous = [IO.File]::ReadAllText($packagePath) | ConvertFrom-Json
        if ($previous.name -ne 'firefox-codex-mcp') { throw 'This directory belongs to another application.' }
    }
    $destinations = New-Object 'System.Collections.Generic.List[object]'
    $seen = @{}
    foreach ($file in $payload.files) {
        if ($file.path -notmatch '^[a-zA-Z0-9][a-zA-Z0-9._/-]*$' -or @($file.path.Split('/') | Where-Object { -not $_ -or $_ -eq '.' -or $_ -eq '..' }).Count -gt 0 -or $seen.ContainsKey($file.path)) { throw 'Invalid companion path.' }
        $seen[$file.path] = $true
        $target = [IO.Path]::GetFullPath((Join-Path $Root $file.path))
        if (-not $target.StartsWith($Root.TrimEnd([char[]]'\/') + [IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase)) { throw 'Companion path escaped installation directory.' }
        Assert-FirefoxOrdinaryPath -Path $target
        $bytes = [Convert]::FromBase64String($file.data)
        $sha = [Security.Cryptography.SHA256]::Create()
        try { $actual = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-', '').ToLowerInvariant() } finally { $sha.Dispose() }
        if ($actual -ne $file.sha256 -or $bytes.Length -gt 4194304) { throw 'Companion file checksum failed.' }
        $destinations.Add([pscustomobject]@{ Path = $target; Bytes = $bytes })
    }
    foreach ($needed in @('package.json', 'package-lock.json', 'scripts/setup.mjs', 'scripts/install-companion.mjs', 'server/native-host.mjs')) {
        if (-not $seen.ContainsKey($needed)) { throw ('Incomplete companion payload: ' + $needed) }
    }
    foreach ($file in $destinations) {
        $null = [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($file.Path))
        $temp = $file.Path + '.' + [Guid]::NewGuid().ToString('N') + '.tmp'
        try {
            [IO.File]::WriteAllBytes($temp, $file.Bytes)
            # Replace the directory entry rather than writing through hardlinks.
            if ([IO.File]::Exists($file.Path)) { [IO.File]::Replace($temp, $file.Path, [NullString]::Value) }
            else { [IO.File]::Move($temp, $file.Path) }
        } finally { if ([IO.File]::Exists($temp)) { [IO.File]::Delete($temp) } }
    }
}

if ($Help) {
    Write-Host 'register.ps1 [-ProjectRoot ABSOLUTE_DIRECTORY] [-NoDownload] [-NoRegisterClients] [-Port 38477]'
    Write-Host 'Installs/updates a local Node.js MCP server and native host, then registers Firefox and supported AI clients.'
    Write-Host 'Server and npm dependencies: about 22 MB, plus Node.js if downloaded. Existing server/setup source files may be replaced.'
    exit 0
}
try {
    Write-Host 'This script installs/updates a local Node.js MCP server and native host, then registers them.'
    Write-Host 'Server and npm dependencies: about 22 MB. A downloaded Node.js runtime requires additional space.'
    Write-Host 'Existing server and setup source files in the selected directory may be replaced.'
    $root = Get-FirefoxSetupRoot -RequestedRoot $ProjectRoot
    Write-Host ('Selected installation directory: ' + $root)
    Expand-FirefoxSetupPayload -Root $root
    $arguments = @{ NoOpenFirefox = $true }
    if ($NoDownload) { $arguments.NoDownload = $true }
    if ($NoRegisterClients) { $arguments.NoRegisterClients = $true }
    if ($PSBoundParameters.ContainsKey('Port')) { $arguments.Port = $Port }
    & (Join-Path $root 'install.ps1') @arguments
    if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
    Write-Host 'Return to the extension settings and choose Check again.'
} catch {
    Write-Host ('Registration failed: ' + $_.Exception.Message) -ForegroundColor Red
    exit 1
}
